using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Gets the current server time in UTC")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("o");
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigurationResource
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the current application configuration data")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            Version = "1.0.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

